document.body.addEventListener('htmx:afterSwap',function(e){const target=e.detail.target;if(!target||!target.classList||!target.classList.contains('hx-slot'))return;if(!target.innerHTML.trim())return;const container=target.closest('[data-accordion]');if(!container)return;const name=container.getAttribute('data-accordion');document.querySelectorAll('[data-accordion="'+name+'"] .hx-slot').forEach(function(slot){if(slot!==target&&!slot.contains(target)&&!target.contains(slot)&&slot.innerHTML.trim())slot.innerHTML=''})});
